const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define Orlando, Florida (using a point and buffering it for a city region)
    const orlando = ee.Geometry.Point([-81.3792, 28.5383]);
    const bufferRadius = 25000; // 25 km buffer around Orlando
    const geometry = orlando.buffer(bufferRadius);

    // 2. Data Acquisition
    // Using the GHSL (Global Human Settlement Layer) built-up area dataset
    // This dataset provides built-up area grids for 1975, 1990, 2000, and 2014.
    // It's ideal for comparing urban extent over time.
    const ghsl = ee.Image('JRC/GHSL/P2016/BUILT_LDSMT_GLOBE_V1');

    // Extract the built-up area bands for 1975 and 2014
    const built1975 = ghsl.select('built_1975');
    const built2014 = ghsl.select('built_2014');

    // Check for image validity (GHSL is a single image, so no empty collection check needed,
    // but we'll check for valid pixels later).

    // 3. Processing: Calculate built-up area for each period
    // The 'built' bands have pixel values representing the presence (1) or absence (0) of built-up area,
    // or sometimes density (0-255). The GHSL documentation suggests built_xxxx is a boolean (0 or 1).
    // Let's treat it as a boolean and sum the pixel count.
    // Ensure data is valid for the region
    const countReducer = ee.Reducer.sum();
    const scale = 1000; // Use a scale of 1000m for area calculation (GHSL resolution is 38m)
    const maxPixels = 1e9;

    // Calculate total built-up area (in square kilometers) for 1975
    // Area of one pixel: (scale * scale) / 1,000,000 (for sq km)
    // Here, we just sum the built-up pixels. Each pixel is roughly 38.28 meters.
    // Let's count pixels and then multiply by approximate pixel area.
    const pixelAreaSqM = ee.Image.pixelArea().mask(built1975).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 38.28, // GHSL nominal resolution
      maxPixels: maxPixels
    }).get('area');

    const builtArea1975_m2 = built1975.gt(0).multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 38.28, // GHSL nominal resolution
      maxPixels: maxPixels
    }).get('built_1975');

    const builtArea2014_m2 = built2014.gt(0).multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 38.28,
      maxPixels: maxPixels
    }).get('built_2014');

    const area1975 = await builtArea1975_m2.getInfo();
    const area2014 = await builtArea2014_m2.getInfo();

    // Check for C2 (No Valid Pixels)
    if (area1975 === null || area2014 === null) {
      console.log("Calculation resulted in null values for built-up area.");
      console.log("C3");
      return;
    }

    // Convert square meters to square kilometers for better readability
    const area1975_km2 = area1975 / 1e6;
    const area2014_km2 = area2014 / 1e6;

    console.log(`Orlando Region (25km buffer):`);
    console.log(`Built-up Area 1975: ${area1975_km2.toFixed(2)} km²`);
    console.log(`Built-up Area 2014: ${area2014_km2.toFixed(2)} km²`);

    // 4. Validation & Final Answer
    if (area1975_km2 === null || area2014_km2 === null || isNaN(area1975_km2) || isNaN(area2014_km2)) {
      console.log("C3"); // Calculation failure
    } else if (area2014_km2 > area1975_km2) {
      console.log("A"); // Yes, built-up area increased
    } else {
      console.log("B"); // No, built-up area did not increase (stayed same or decreased)
    }

  } catch (e) {
    console.log(`Error during analysis: ${e.message}`);
    if (e.message.includes('image, collection, or band names are incorrect') ||
        e.message.includes('syntax or method error') ||
        e.message.includes('memory limit exceeded')) {
      console.log("D");
    } else {
      console.log("C3"); // Generic failure
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
